    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 10px 0 14px;
    position: sticky;
    top: 0;
    z-index: 50;
    background: var(--c-surface-2);
    backdrop-filter: blur(24px) saturate(180%);
    -webkit-backdrop-filter: blur(24px) saturate(180%);
    border-bottom: 1px solid var(--c-border);
    box-shadow: 0 1px 0 0 color-mix(in srgb, var(--accent) 25%, transparent);
  }

  .icon-btn {
    width: 46px;
    height: 46px;
    border: 1px solid var(--c-border-md);
    border-radius: 14px;
    background: var(--c-glass-sm);
    color: var(--c-text);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background var(--t-base, 180ms ease), border-color var(--t-base, 180ms ease), transform 80ms ease;
  }

  .icon-btn:hover { background: var(--c-glass-hover); border-color: var(--c-border-2); }
  .icon-btn:active { transform: scale(0.93); }
  .icon-btn.refresh:hover { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 50%, transparent); }
  .icon-btn:disabled { opacity: 0.5; cursor: not-allowed; }

  .title-block { text-align: center; }

  .eyebrow {
    display: block;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 10px;
    font-weight: 800;
  }

  .title-block h1 { font-size: 21px; margin: 2px 0 0; letter-spacing: -0.02em; font-weight: 900; }

  .title-sport-ic {
    display: inline-flex;
    margin-top: 3px;
    filter: drop-shadow(0 0 8px color-mix(in srgb, var(--accent) 60%, transparent));
  }

  .placeholder {
    padding: 40px 0;
    text-align: center;
    color: var(--c-text-dim, var(--c-text));
    font-size: 13px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
  }

