  .cta:active { transform: scale(0.985); }
  .cta:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none; }

  /* ── League groups ── */
  .league-group { margin-bottom: 18px; }

  .league-title {
    display: flex;
